 auto metric=[&](std::u16string_view value,const C4Font& f){auto m=measurements.measure(value,f);if(!m)throw std::runtime_error(m.error());return *m;};
 auto legacy=[&](std::u16string_view value,C4Font f){auto a=metric(value,f);f.family=u"sans-serif";auto b=metric(value,f);a.width=std::round(a.width);a.height=std::round(a.height);b.width=std::round(b.width);b.height=std::round(b.height);return b.height>a.height&&b.width>a.width?b:a;};
 auto make_label=[&](std::u16string_view value,C4Font f,double width){Label l;l.font=f;if(value.empty())return l;std::u16string line;for(std::size_t p=0;p<value.size();){auto end=value.find(u' ',p);if(end==value.npos)end=value.size();auto word=value.substr(p,end-p);auto next=line.empty()?std::u16string(word):line+u" "+std::u16string(word);if(c.wrap&&!line.empty()&&metric(next,f).advance>width){l.lines.push_back(line);line=word;}else line=std::move(next);p=end+1;}l.lines.push_back(line);for(const auto& item:l.lines)l.w=std::max(l.w,metric(item,f).width);l.h=metric(value,f).height+(l.lines.size()-1)*f.size*1.1;return l;};
 std::vector<ShapeLayout> shapes(d.shapes.size());std::vector<Box> boundaries(d.boundaries.size());std::vector<double> boundary_label_y(d.boundaries.size()),boundary_type_y(d.boundaries.size()),boundary_descr_y(d.boundaries.size());
 for(std::size_t i=0;i<d.shapes.size();++i){const auto& s=d.shapes[i];auto& l=shapes[i];auto f=font(c.original,s.type);std::u16string type=s.type;if(type.starts_with(u"external_"))type.erase(0,9);if(type.ends_with(u"_db"))type.resize(type.size()-3);if(type.ends_with(u"_queue"))type.resize(type.size()-6);std::u16string stereotype=type==u"person"?u"Person":type==u"system"?u"Software System":type==u"container"?u"Container":u"Component";stereotype=u"["+stereotype+(s.technology&&!s.technology->empty()?u": "+*s.technology:u"")+u"]";const bool db=s.type.ends_with(u"_db");const auto wrap_width=std::max(32.0,c.width-(db?3:2)*pad);auto name_font=f;name_font.weight=700;l.labels.push_back(make_label(s.label,name_font,wrap_width));auto type_font=f;type_font.size*=.75;l.labels.push_back(make_label(stereotype,type_font,wrap_width));if(!s.description.empty()){f.size*=.82;l.labels.push_back(make_label(s.description,f,wrap_width));}for(const auto& label:l.labels){l.label_w=std::max(l.label_w,label.w);l.label_h+=label.h+3;}l.label_h-=3;l.box.w=std::max(c.width,l.label_w+2*pad);l.box.h=l.label_h+2*pad;if(s.type==u"person"||s.type==u"external_person"){l.box.w=std::max(l.box.w,100.0);l.radius=std::min(std::max(l.box.w*.23,16.0),56.0);l.body_height=l.box.h;l.box.h+=l.radius*1.73;}else if(db){l.box.w=std::max(c.width-pad,l.label_w)+pad;l.radius=(l.box.w/2)/(2.5+l.box.w/50);l.box.h=l.label_h+pad+3*l.radius;}}
