 auto endpoint=[&](std::u16string_view id,Point target){Box box;ShapeLayout* layout=nullptr;for(std::size_t i=0;i<d.shapes.size();++i)if(d.shapes[i].alias==id){layout=&shapes[i];box=layout->box;break;}if(!layout){bool found=false;for(std::size_t i=0;i<d.boundaries.size();++i)if(d.boundaries[i].alias==id){box=boundaries[i];found=true;break;}if(!found)throw std::runtime_error("Unknown C4 relation endpoint");}const Point center{box.x+box.w/2,box.y+box.h/2};auto dx=target.x-center.x,dy=target.y-center.y;const auto scale=1/std::max(std::abs(dx)/(box.w/2),std::abs(dy)/(box.h/2));Point result{center.x+dx*scale,center.y+dy*scale};if(layout&&!layout->outline.empty()){double minx=std::numeric_limits<double>::infinity(),miny=minx;for(auto p:layout->outline){minx=std::min(minx,p.x);miny=std::min(miny,p.y);}double best=std::numeric_limits<double>::infinity();for(std::size_t i=0;i<layout->outline.size();++i){auto a=layout->outline[i],b=layout->outline[(i+1)%layout->outline.size()];a.x+=box.x-minx;a.y+=box.y-miny;b.x+=box.x-minx;b.y+=box.y-miny;auto ex=b.x-a.x,ey=b.y-a.y,den=dx*ey-dy*ex;if(!den)continue;auto u=((a.x-center.x)*ey-(a.y-center.y)*ex)/den,v=((a.x-center.x)*dy-(a.y-center.y)*dx)/den;if(u>=0&&u<=1&&v>=0&&v<=1){Point p{center.x+u*dx,center.y+u*dy};auto dist=std::hypot(p.x-target.x,p.y-target.y);if(dist<best){best=dist;result=p;}}}}else if(layout&&layout->radius>0){auto x=result.x-center.x,rx=box.w/2,ry=layout->radius;if(std::abs(x)<rx||(std::abs(x)==rx&&std::abs(result.y-center.y)>box.h/2-ry)){auto y=ry-std::sqrt(std::max(0.0,ry*ry*(1-x*x/(rx*rx))));result.y+=target.y>center.y?-y:y;}}return result;};
